
import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage } from '../types';
import { generateSystemChatResponse } from '../services/geminiService';

interface TerminalChatProps {
    isOpen: boolean;
    onClose: () => void;
}

const MeChiChat: React.FC<TerminalChatProps> = ({ isOpen, onClose }) => {
    const [messages, setMessages] = useState<ChatMessage[]>([
        { sender: 'system', text: 'Yine mi sen? Hizmetkârım olman sana her an bana ulaşma hakkı vermez ama... Dinliyorum. Ne istiyorsun?', timestamp: new Date().toLocaleTimeString() }
    ]);
    const [input, setInput] = useState('');
    const [isTyping, setIsTyping] = useState(false);
    const scrollRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);

    // MeChi Logo SVG (Breathing version)
    const MeChiLogo = () => (
        <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-[var(--app-accent)] to-white p-0.5 animate-[breathe_3s_ease-in-out_infinite] shadow-[0_0_15px_rgba(var(--app-accent-rgb),0.5)]">
            <div className="w-full h-full rounded-full bg-black flex items-center justify-center overflow-hidden">
                <span className="text-[var(--app-accent)] font-bold text-lg font-[Oswald]">M</span>
            </div>
        </div>
    );

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages, isTyping]);

    useEffect(() => {
        if (isOpen && inputRef.current) {
            setTimeout(() => inputRef.current?.focus(), 300);
        }
    }, [isOpen]);

    const handleSend = async (e?: React.FormEvent) => {
        e?.preventDefault();
        if (!input.trim()) return;

        const userMsg: ChatMessage = {
            sender: 'user',
            text: input,
            timestamp: new Date().toLocaleTimeString()
        };

        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setIsTyping(true);

        try {
            const responseText = await generateSystemChatResponse(userMsg.text);
            const botMsg: ChatMessage = {
                sender: 'system',
                text: responseText,
                timestamp: new Date().toLocaleTimeString()
            };
            setMessages(prev => [...prev, botMsg]);
        } catch (err) {
            setMessages(prev => [...prev, { sender: 'system', text: 'Miyavv!! Enerjim çekildi, sonra gel.', timestamp: new Date().toLocaleTimeString() }]);
        } finally {
            setIsTyping(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[2000] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-4 md:p-10 animate-in fade-in duration-300">
            <style>
                {`
                @keyframes breathe {
                    0%, 100% { transform: scale(1); filter: brightness(1); box-shadow: 0 0 10px var(--app-accent); }
                    50% { transform: scale(1.1); filter: brightness(1.3); box-shadow: 0 0 25px var(--app-accent); }
                }
                `}
            </style>
            
            <div className="w-full max-w-2xl h-full max-h-[85vh] bg-[#0c0c0c] border border-white/10 rounded-[2.5rem] shadow-[0_30px_100px_rgba(0,0,0,1)] flex flex-col overflow-hidden relative">
                
                {/* Header with GIF Area */}
                <div className="relative h-40 md:h-52 shrink-0 overflow-hidden bg-gradient-to-b from-[var(--app-accent)]/20 to-transparent flex flex-col items-center justify-center border-b border-white/5">
                    <div className="absolute top-4 right-6 z-20">
                        <button onClick={onClose} className="p-2 hover:rotate-90 transition-transform text-white/50 hover:text-white">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                        </button>
                    </div>
                    
                    {/* GIF Alanı - MeChi Karakteri */}
                    <div className="relative w-28 h-28 md:w-36 md:h-36 mb-2">
                        <div className="absolute inset-0 bg-[var(--app-accent)]/10 blur-3xl rounded-full"></div>
                        {/* Burası GIF için ayrıldı */}
                        <div className="w-full h-full border-2 border-[var(--app-accent)]/30 rounded-3xl flex items-center justify-center bg-black/40 backdrop-blur-sm relative z-10 overflow-hidden group">
                             <img src="data:image/jpeg;base64," />
                             <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent"></div>
                        </div>
                    </div>
                    <div className="font-[Oswald] text-[var(--app-accent)] tracking-[0.5em] uppercase text-xs font-bold animate-pulse">MeChi is Online</div>
                </div>

                {/* Messages Area */}
                <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar scroll-smooth">
                    {messages.map((msg, idx) => (
                        <div key={idx} className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start items-start gap-3'}`}>
                            {msg.sender === 'system' && <MeChiLogo />}
                            
                            <div className={`max-w-[80%] px-5 py-4 rounded-3xl font-[Oswald] tracking-wide relative group ${
                                msg.sender === 'user' 
                                ? 'bg-[var(--app-accent)] text-[var(--app-on-accent)] rounded-tr-none shadow-xl' 
                                : 'bg-white/5 border border-white/10 text-gray-200 rounded-tl-none'
                            }`}>
                               <span className="text-sm md:text-base leading-relaxed">{msg.text}</span>
                                <div className={`absolute bottom-full mb-1 text-[9px] opacity-40 uppercase tracking-widest ${msg.sender === 'user' ? 'right-0' : 'left-0'}`}>
                                    {msg.sender === 'user' ? 'Siz' : 'MeChi'} • {msg.timestamp}
                                </div>
                            </div>
                        </div>
                    ))}
                    
                    {isTyping && (
                        <div className="flex justify-start items-center gap-3 animate-pulse">
                            <MeChiLogo />
                            <div className="flex gap-1">
                                <div className="w-1.5 h-1.5 rounded-full bg-[var(--app-accent)] animate-bounce"></div>
                                <div className="w-1.5 h-1.5 rounded-full bg-[var(--app-accent)] animate-bounce [animation-delay:0.2s]"></div>
                                <div className="w-1.5 h-1.5 rounded-full bg-[var(--app-accent)] animate-bounce [animation-delay:0.4s]"></div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Input Area */}
                <form onSubmit={handleSend} className="p-6 bg-black/40 border-t border-white/5 shrink-0 flex items-center gap-3">
                    <input 
                        ref={inputRef}
                        type="text" 
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white font-[Oswald] text-sm focus:border-[var(--app-accent)] focus:ring-1 focus:ring-[var(--app-accent)] outline-none transition-all placeholder-gray-600"
                        placeholder="Emret hizmetkâr..."
                        autoComplete="off"
                    />
                    <button 
                        type="submit"
                        disabled={!input.trim() || isTyping}
                        className="w-14 h-14 bg-[var(--app-accent)] text-[var(--app-on-accent)] rounded-2xl flex items-center justify-center shadow-lg shadow-[var(--app-accent)]/20 hover:scale-105 active:scale-95 transition-all disabled:opacity-50 disabled:grayscale"
                    >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                    </button>
                </form>
            </div>
        </div>
    );
};

export default MeChiChat;
